    cost_so_far = {}
    queue = [start]
    came_from[start] = None
    cost_so_far[start] = 0
    while queue:
        current = queue[0]
        queue = queue[1:]
        if current == goal:
            break
        for next_node in graph[current]:
            if next_node not in cost_so_far:
                queue.append(next_node)
                came_from[next_node] = current
                cost_so_far[next_node] = cost_so_far[current] + 1
    path = []
    if goal in came_from:
        current = goal
        while current != start:
            path.insert(0, current)
            current = came_from[current]
        path.insert(0, start)
        return path
    else:
        return None

