def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    if start == goal:
        return [start]
    priority_queue = [(0, start)]
    visited = set()
    edge_to = {node: None for node in graph}
    cost_so_far = {node: float('infinity') for node in graph}
    cost_so_far[start] = 0
    while len(priority_queue) > 0:
        _, current = heapq.heappop(priority_queue)
        if current in visited:
            continue
        visited.add(current)
        if current is goal:
            path = []
            while current in edge_to:
                path.append(current)
                current = edge_to[current]
            return path[::-1]
        for next_node in graph[current]:
            if next_node in visited:
                continue
            old_cost = cost_so_far[current]
            new_cost = old_cost + 1
            if new_cost < cost_so_far[next_node]:
                cost_so_far[next_node] = new_cost
                priority = cost_so_far[next_node]
                edge_to[next_node] = current
                heapq.heappush(priority_queue, (new_cost, next_node))
    return None
